class Token:
    def __init__(self, supply, creator):
        self.balances = {creator: supply}
        self.allowances = {}               # (owner, spender) -> amount
        self.events = []

    def balance_of(self, who):
        return self.balances.get(who, 0)

    def allowance(self, owner, spender):
        return self.allowances.get((owner, spender), 0)

    def _move(self, frm, to, amount):
        if not isinstance(amount, int) or amount < 0:
            raise ValueError("bad amount")
        if self.balance_of(frm) < amount:
            raise ValueError("insufficient balance")
        self.balances[frm] = self.balance_of(frm) - amount
        self.balances[to] = self.balance_of(to) + amount
        self.events.append(("Transfer", frm, to, amount))

    def transfer(self, sender, to, amount):
        self._move(sender, to, amount)
        return True

    def approve(self, owner, spender, amount):
        if not isinstance(amount, int) or amount < 0:
            raise ValueError("bad amount")
        self.allowances[(owner, spender)] = amount
        self.events.append(("Approval", owner, spender, amount))
        return True

    def transfer_from(self, spender, owner, to, amount):
        allowed = self.allowance(owner, spender)
        if not isinstance(amount, int) or amount < 0 or allowed < amount:
            raise ValueError("allowance too small")
        self._move(owner, to, amount)      # raises before any change if the balance is short
        self.allowances[(owner, spender)] = allowed - amount
        return True

TRANSFER_SELECTOR = "a9059cbb"   # first 4 bytes of keccak256("transfer(address,uint256)")

def encode_transfer(to, amount):
    hex_addr = to[2:] if to.startswith("0x") else to
    if len(hex_addr) != 40:
        raise ValueError("an address is 20 bytes")
    address = int(hex_addr, 16)              # raises ValueError if not hexadecimal
    if not isinstance(amount, int) or not 0 <= amount < 2**256:
        raise ValueError("amount must fit in a uint256")
    return TRANSFER_SELECTOR + address.to_bytes(32, "big").hex() + amount.to_bytes(32, "big").hex()

exercises.solution:
```python
TRANSFER_SELECTOR = "a9059cbb"

def encode_transfer(to, amount):
    hex_addr = to[2:] if to.startswith("0x") else to
    if len(hex_addr) != 40:
        raise ValueError("an address is 20 bytes")
    address = int(hex_addr, 16)
    if not isinstance(amount, int) or not 0 <= amount < 2**256:
        raise ValueError("amount must fit in a uint256")
    return TRANSFER_SELECTOR + address.to_bytes(32, "big").hex() + amount.to_bytes(32, "big").hex()
```

The result is $4 + 32 + 32 = 68$ bytes, 136 hex digits, and for the lesson's example it matches the output of the Keccak program exactly. Wallets show users a decoded form of this data; when they cannot (an unknown contract, a raw signature request), the user is effectively signing bytes they cannot read, which is how many phishing attacks succeed. A careful encoder also rejects values that do not fit the type, because a contract would read only the last 32 bytes it expects and silently misinterpret anything else.
